(()=>{'use strict';
const all=(FLOWER_CONTENT.readyBouquets||[]).filter(b=>b.id&&b.name&&b.image),section=document.querySelector('#hazir-buketler');if(!all.length)return;
const groups=[['all','Tümü'],['flowers','Çiçek buketleri'],['toys','Oyuncaklı buketler'],['potted','Saksı çiçekleri'],['arrangement','Aranjmanlar'],['wreath','Çelenkler'],['funeral','Cenaze çelenkleri']];let query='',active='all',page=1,pageSize=20,photos=[],photoIndex=0,current=null;
const grid=document.querySelector('#ready-grid'),pagination=document.querySelector('#ready-pagination'),pageSizeSelect=document.querySelector('#ready-page-size'),filters=document.querySelector('#ready-filters');
const dialog=document.createElement('dialog');dialog.className='bouquet-photo-dialog';dialog.setAttribute('aria-label','Yade ürün fotoğrafı');
const close=document.createElement('button');close.className='dialog-close';close.type='button';close.setAttribute('aria-label','Fotoğrafı kapat');close.textContent='×';
const large=document.createElement('img'),caption=document.createElement('p'),nav=document.createElement('div');nav.className='ready-photo-nav';const prev=document.createElement('button'),next=document.createElement('button'),position=document.createElement('span');prev.type=next.type='button';prev.textContent='← Önceki';next.textContent='Sonraki →';nav.append(prev,position,next);const enquire=document.createElement('a');enquire.className='ready-dialog-enquire';enquire.target='_blank';enquire.rel='noopener noreferrer';enquire.textContent='BU TASARIMI İSTİYORUM ↗';dialog.append(close,large,caption,nav,enquire);document.body.append(dialog);
function url(b){return'https://wa.me/'+FLOWER_CONTENT.whatsapp+'?text='+encodeURIComponent('Merhaba Yade Flowers, sitenizdeki “'+b.name+'” ('+b.id+') tasarımını beğendim. Güncel fiyatı ve hazırlama ve dükkândan alma uygunluğu hakkında bilgi alabilir miyim?')}
function showPhoto(){large.src=photos[photoIndex];large.alt=current.alt||current.name;caption.textContent=current.name+' · '+current.id;position.textContent=(photoIndex+1)+' / '+photos.length;nav.hidden=photos.length<2;enquire.href=url(current)}
function open(b){current=b;photos=[b.image,...(b.images||[])];photoIndex=0;showPhoto();dialog.showModal()}
close.onclick=()=>dialog.close();prev.onclick=()=>{photoIndex=(photoIndex-1+photos.length)%photos.length;showPhoto()};next.onclick=()=>{photoIndex=(photoIndex+1)%photos.length;showPhoto()};dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();next.click()}if(e.key==='ArrowLeft'){e.preventDefault();prev.click()}});dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}};
for(const [id,label]of groups){if(id!=='all'&&!all.some(b=>b.category===id))continue;const btn=document.createElement('button');btn.type='button';btn.dataset.filter=id;btn.textContent=label;btn.setAttribute('aria-pressed',String(id===active));btn.onclick=()=>{active=id;page=1;render()};filters.append(btn)}

function goToPage(value){page=value;render();const count=document.querySelector('#ready-count');count.tabIndex=-1;count.focus({preventScroll:true});document.querySelector('.ready-collection-meta').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function renderPagination(pageCount,total){pagination.replaceChildren();pagination.hidden=total===0||pageCount<=1;if(pagination.hidden)return;
function button(label,target,disabled=false,current=false){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=disabled;if(current)b.setAttribute('aria-current','page');if(/^\d+$/.test(label))b.setAttribute('aria-label',label+'. sayfa');b.onclick=()=>goToPage(target);pagination.append(b)}
button('← Önceki',page-1,page===1);const pages=[...new Set([1,page-1,page,page+1,pageCount])].filter(n=>n>=1&&n<=pageCount).sort((a,b)=>a-b);let last=0;for(const n of pages){if(last&&n-last>1){const dots=document.createElement('span');dots.textContent='…';dots.setAttribute('aria-hidden','true');pagination.append(dots)}button(String(n),n,false,n===page);last=n}button('Sonraki →',page+1,page===pageCount);const status=document.createElement('span');status.className='ready-page-status';status.textContent=page+' / '+pageCount+' sayfa';pagination.append(status)}
function normalize(value){return value.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,' ').trim()}
function render(){const terms=normalize(query).split(/\s+/).filter(Boolean);const codeMatch=query.match(/^yd[\s-]*(\d+)$/i);const items=all.filter(b=>(active==='all'||b.category===active)&&(codeMatch?Number(b.id.replace(/\D/g,''))===Number(codeMatch[1]):terms.every(term=>normalize(b.name+' '+b.id).includes(term)))),pageCount=Math.max(1,Math.ceil(items.length/pageSize));page=Math.min(page,pageCount);const offset=(page-1)*pageSize,visible=items.slice(offset,offset+pageSize);grid.replaceChildren();for(const b of visible){const card=document.createElement('article');card.className='ready-card';const zoom=document.createElement('button');zoom.className='ready-photo';zoom.type='button';zoom.setAttribute('aria-label',b.name+' fotoğrafını büyüt');const img=document.createElement('img');img.src=b.image;img.alt=b.alt||b.name;img.loading='lazy';img.decoding='async';img.width=800;img.height=1000;const badge=document.createElement('span');badge.className='ready-product-code';badge.textContent=b.id;const flowerTop=document.createElement('span'),flowerBottom=document.createElement('span'),dot=document.createElement('i');flowerTop.className='ready-frame-flower frame-top';flowerBottom.className='ready-frame-flower frame-bottom';dot.className='ready-frame-dot';for(const decoration of [flowerTop,flowerBottom,dot])decoration.setAttribute('aria-hidden','true');zoom.append(flowerTop,flowerBottom,dot,img,badge);zoom.onclick=()=>open(b);const info=document.createElement('div');info.className='ready-info';const name=document.createElement('h3');name.textContent=b.name;const price=document.createElement('p');price.textContent=Number.isSafeInteger(b.price)&&b.price>=0?BouquetModel.money(b.price):'Fiyat ve uygunluk için bize sor';const link=document.createElement('a');link.className='ready-enquire';link.target='_blank';link.rel='noopener noreferrer';link.textContent='BUNU İSTİYORUM ↗';link.href=url(b);info.append(name,price,link);card.append(zoom,info);grid.append(card)}if(!items.length){const empty=document.createElement('div');empty.className='ready-empty';const title=document.createElement('h3');title.textContent='Bu isimde bir tasarım bulamadık.';const tip=document.createElement('p');tip.textContent='Daha kısa bir kelime dene veya tüm ürünlere dön.';const reset=document.createElement('button');reset.type='button';reset.textContent='Tüm ürünleri göster ↗';reset.onclick=()=>{query='';active='all';page=1;searchInput.value='';clear.hidden=true;render();searchInput.focus()};empty.append(title,tip,reset);grid.append(empty)}clear.hidden=!query;document.querySelector('#ready-count').textContent=(query?'Arama: '+query+' · ':'')+(items.length?offset+1:0)+'–'+(offset+visible.length)+' / '+items.length+' tasarım';renderPagination(pageCount,items.length);filters.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===active)))}
const searchInput=document.querySelector('#ready-query'),clear=document.querySelector('#ready-clear');function search(){query=searchInput.value.trim();active='all';page=1;render()}searchInput.addEventListener('input',search);document.querySelector('#ready-search').onsubmit=e=>{e.preventDefault();search()};clear.onclick=()=>{searchInput.value='';search();searchInput.focus()};pageSizeSelect.onchange=()=>{pageSize=Number(pageSizeSelect.value);page=1;render()};render();section.hidden=false;
})();
